/// <summary>
///     The <c>AVASalesQuotationTotalsFrm_Extension</c> class is the extension for <c>SalesQuotationTotals</c>
/// </summary>
[ExtensionOf(FormStr(SalesQuotationTotals))]
final class AVASalesQuotationTotalsFrm_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>setDisplayFields</c> method.
/// </summary>
void  setDisplayFields()
{
    FormDataSource          locAVASpecialDiscQuotationDS;
    AVASpecialDiscQuotation locAVASpecialDiscQuotation;

    Percent                 locAllDiscountFactor;

    locAVASpecialDiscQuotationDS    = this.AVASpecialDiscQuotation_DS;
    locAVASpecialDiscQuotation      = locAVASpecialDiscQuotationDS.cursor();


    next setDisplayFields();

    locAllDiscountFactor = locAVASpecialDiscQuotation.AllDiscountFactor;
    locAllDiscountFactor = minOne(locAllDiscountFactor);

    if(     locAVASpecialDiscQuotation.RecId 
        &&  locAllDiscountFactor                != 1 
        &&  locAllDiscountFactor                != 0   )
    {
        AVASpecialDiscQuotation_Group.visible(true);

        if(     locAVASpecialDiscQuotation.SpecialDiscountId1
            &&  locAVASpecialDiscQuotation.SpecialDiscountPct1 != 0 )
        {
            AVASpecialDiscQuotationSD1_Group.visible(true);
        }
        else
        {
            AVASpecialDiscQuotationSD1_Group.visible(false);
        }

        if(     locAVASpecialDiscQuotation.SpecialDiscountId2
            &&  locAVASpecialDiscQuotation.SpecialDiscountPct2 != 0 )
        {
            AVASpecialDiscQuotationSD2_Group.visible(true);
        }
        else
        {
            AVASpecialDiscQuotationSD2_Group.visible(false);
        }

        if(     locAVASpecialDiscQuotation.SpecialDiscountId3
            &&  locAVASpecialDiscQuotation.SpecialDiscountPct3 != 0 )
        {
            AVASpecialDiscQuotationSD3_Group.visible(true);
        }
        else
        {
            AVASpecialDiscQuotationSD3_Group.visible(false);
        }
        SumMarkup.realValue(SumMarkup.realValue() * locAllDiscountFactor);
        SumTax.realValue(SumTax.realValue() * locAllDiscountFactor);
        InvoiceAmount.realValue(InvoiceAmount.realValue() * locAllDiscountFactor);
        SpecialDiscountSumLines.realValue(SumLines.realValue() * locAllDiscountFactor);
        SpecialDiscountEndDisc.realValue(SumLines.realValue() - SpecialDiscountSumLines.realValue());
        CashDisc.realValue(CashDisc.realValue() * locAllDiscountFactor);
    }
    else
    {
        AVASpecialDiscQuotation_Group.visible(false);
    }
}
